// src/api/auth/signupAPI.js
import axios_api from "../axios";
import { apiPath, IS_DEMO } from "../config";

const host = apiPath("/signup");

export const getUserInfo = async () => {
  // 데모에선 빈 객체든 seed든 적당히 리턴(어차피 보호 라우터가 우회)
  if (IS_DEMO) return { userName: "demo" };
  const res = await axios_api.get(host);
  return res.data;
};

export const createUserInfo = async (formData) => {
  if (IS_DEMO) {
    // 데모면 바로 성공 응답 흉내
    return { success: true, userNo: 1, userName: String(formData.userName || "demo") };
  }
  const payload = {
    userName: String(formData.userName || "").trim(),
    loginId:  String(formData.loginId  || "").trim(),
    password: String(formData.password || ""),
  };
  const res = await axios_api.post(host, payload);
  return res.data;
};
